          "id": "code-ml-35-1-ch35_1_diag",
          "title": "Production Audit: Online Redis vs Offline PIT Replay Shadow Parity Auditor & CI/CD Block Gate",
          "language": "python",
          "filename": "35_1_shadow_feature_parity_auditor.py",
          "code": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\n\nrng = np.random.default_rng(42)\nn_req = 1000\nfeature_names = [\"log_spend_ratio\", \"tx_count_1h\", \"acct_age_days\", \"geo_velocity_kmh\"]\n\n# 1. Offline Feature Store Replay (Ground-Truth Point-in-Time untuk 1.000 request)\nX_offline = np.column_stack([\n    rng.normal(0.5, 0.7, size=n_req),\n    rng.poisson(2.4, size=n_req).astype(float),\n    rng.uniform(10.0, 900.0, size=n_req),\n    rng.exponential(18.0, size=n_req),\n])\noff_nan_mask = rng.random(n_req) < 0.08\nX_offline[off_nan_mask, 3] = np.nan\n\n# 2. Online Feature Store Shadow Log (Redis): cache miss 6% -> 0.0 & stale/sentinel -1.0 pada geo_velocity\nX_online = X_offline.copy()\ncache_miss = rng.random(n_req) < 0.06\nX_online[cache_miss, 1] = 0.0\nX_online[:, 3] = np.where(np.isnan(X_online[:, 3]), -1.0, X_online[:, 3] * 1.18 + 3.5)\nX_online[:, 0] = X_online[:, 0].astype(np.float32).astype(np.float64)\n\nX_tr = np.column_stack([\n    rng.normal(0.5, 0.7, size=1200),\n    rng.poisson(2.4, size=1200).astype(float),\n    rng.uniform(10.0, 900.0, size=1200),\n    rng.exponential(18.0, size=1200),\n])\ny_tr = rng.binomial(\n    1,\n    1.0 / (1.0 + np.exp(-(-2.2 + 0.9 * X_tr[:, 0] + 0.35 * X_tr[:, 1] - 0.002 * X_tr[:, 2] + 0.04 * X_tr[:, 3]))),\n)\nclf = LogisticRegression(random_state=42).fit(X_tr, y_tr)\n\ndef compute_psi(ref_arr: np.ndarray, cur_arr: np.ndarray, n_bins: int = 10) -> float:\n    ref_v, cur_v = ref_arr[~np.isnan(ref_arr)], cur_arr[~np.isnan(cur_arr)]\n    edges = np.unique(np.quantile(ref_v, np.linspace(0.0, 1.0, n_bins + 1)))\n    edges[0], edges[-1] = -np.inf, np.inf\n    p = np.clip(np.histogram(ref_v, bins=edges)[0] / len(ref_v), 1e-6, None)\n    q = np.clip(np.histogram(cur_v, bins=edges)[0] / len(cur_v), 1e-6, None)\n    return float(np.sum((q - p) * np.log(q / p)))\n\nprint(\"=== SHADOW PARITY AUDIT: OFFLINE PIT REPLAY vs ONLINE REDIS (N=1000) ===\")\nviolations = []\nfor j, name in enumerate(feature_names):\n    off_col, on_col = X_offline[:, j], X_online[:, j]\n    null_mismatch = float(np.mean(np.isnan(off_col) != np.isnan(on_col)))\n    both_valid = (~np.isnan(off_col)) & (~np.isnan(on_col))\n    mae = float(np.mean(np.abs(on_col[both_valid] - off_col[both_valid])))\n    p99_err = float(np.quantile(np.abs(on_col[both_valid] - off_col[both_valid]), 0.99))\n    psi = compute_psi(off_col, on_col)\n    status = \"FAIL\" if (null_mismatch > 0.01 or psi > 0.10 or p99_err > 1.0) else \"PASS\"\n    if status == \"FAIL\":\n        violations.append(name)\n    print(f\"  {name:18s} | NullMismatch={null_mismatch:6.2%} | MAE={mae:7.4f} | p99Err={p99_err:7.4f} | PSI={psi:.4f} | [{status}]\")\n\nX_off_imp = np.where(np.isnan(X_offline), 12.5, X_offline)\nX_on_imp = np.where(np.isnan(X_online), 12.5, X_online)\ns_off = clf.predict_proba(X_off_imp)[:, 1]\ns_on = clf.predict_proba(X_on_imp)[:, 1]\nscore_psi = compute_psi(s_off, s_on)\nflip_rate = float(np.mean((s_off >= 0.5) != (s_on >= 0.5)))\ngate = \"BLOCK_DEPLOY\" if (len(violations) > 0 or flip_rate > 0.02) else \"ALLOW_PROMOTE\"\nprint(f\"Score Parity -> Max|ds|={np.max(np.abs(s_on - s_off)):.4f} | Score PSI={score_psi:.4f} | Decision Flip={flip_rate:.2%}\")\nprint(f\"CI/CD Parity Gate Decision: {gate} (Violating features: {violations})\")",
          "expectedOutput": "=== SHADOW PARITY AUDIT: OFFLINE PIT REPLAY vs ONLINE REDIS (N=1000) ===\n  log_spend_ratio    | NullMismatch= 0.00% | MAE= 0.0000 | p99Err= 0.0000 | PSI=0.0000 | [PASS]\n  tx_count_1h        | NullMismatch= 0.00% | MAE= 0.1450 | p99Err= 4.0000 | PSI=0.0299 | [FAIL]\n  acct_age_days      | NullMismatch= 0.00% | MAE= 0.0000 | p99Err= 0.0000 | PSI=0.0000 | [PASS]\n  geo_velocity_kmh   | NullMismatch= 7.90% | MAE= 6.6405 | p99Err=18.9082 | PSI=1.1917 | [FAIL]\nScore Parity -> Max|ds|=0.5911 | Score PSI=0.0210 | Decision Flip=5.40%\nCI/CD Parity Gate Decision: BLOCK_DEPLOY (Violating features: ['tx_count_1h', 'geo_velocity_kmh'])",
