          "title": "Scikit-Learn 1.9 + Safe Zero-Pickle Bundle: Manifest JSON + .npy allow_pickle=False + HMAC/SHA-256",
          "language": "python",
          "filename": "35_2_safe_zero_pickle_manifest_hmac_parity.py",
          "code": "import hashlib\nimport hmac\nimport io\nimport json\nimport zipfile\nimport numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\n\n# 1. Latih Pipeline Scikit-Learn 1.9 deterministik\nX, y = make_classification(\n    n_samples=600, n_features=8, n_informative=5, n_redundant=2, random_state=42\n)\npipe = Pipeline([\n    (\"scaler\", StandardScaler()),\n    (\"clf\", LogisticRegression(C=1.0, random_state=42)),\n])\npipe.fit(X, y)\nprobs_orig = pipe.predict_proba(X[:100])[:, 1]\n\n# 2. Safe Zero-Pickle Model Bundle Builder (pola skops + SafeTensors + HMAC-SHA256)\nSECRET_KEY = b\"velqora-prod-kms-key-2026-v1\"\n\ndef save_safe_bundle(trained_pipe: Pipeline, key: bytes) -> bytes:\n    scaler, clf = trained_pipe.named_steps[\"scaler\"], trained_pipe.named_steps[\"clf\"]\n    tensors = {\n        \"scaler_mean.npy\": np.asarray(scaler.mean_, dtype=np.float64),\n        \"scaler_scale.npy\": np.asarray(scaler.scale_, dtype=np.float64),\n        \"clf_coef.npy\": np.asarray(clf.coef_, dtype=np.float64),\n        \"clf_intercept.npy\": np.asarray(clf.intercept_, dtype=np.float64),\n    }\n    buf = io.BytesIO()\n    tensor_hashes = {}\n    with zipfile.ZipFile(buf, \"w\", compression=zipfile.ZIP_DEFLATED) as zf:\n        for fname, arr in tensors.items():\n            abuf = io.BytesIO()\n            np.save(abuf, arr, allow_pickle=False)\n            raw_npy = abuf.getvalue()\n            tensor_hashes[fname] = {\n                \"shape\": list(arr.shape),\n                \"dtype\": str(arr.dtype),\n                \"sha256\": hashlib.sha256(raw_npy).hexdigest(),\n            }\n            zf.writestr(fname, raw_npy)\n        manifest_body = {\n            \"schema_version\": \"velqora-safe-linear-v1\",\n            \"allowed_ops\": [\"StandardScaler\", \"LogisticRegression\"],\n            \"tensors\": tensor_hashes,\n        }\n        canonical_json = json.dumps(manifest_body, sort_keys=True, separators=(\",\", \":\")).encode(\"utf-8\")\n        sig = hmac.new(key, canonical_json, hashlib.sha256).hexdigest()\n        zf.writestr(\"manifest.json\", json.dumps({\"manifest\": manifest_body, \"hmac_sha256\": sig}, indent=2))\n    return buf.getvalue()\n\ndef load_and_verify_safe_bundle(bundle_bytes: bytes, key: bytes) -> dict[str, np.ndarray]:\n    with zipfile.ZipFile(io.BytesIO(bundle_bytes), \"r\") as zf:\n        envelope = json.loads(zf.read(\"manifest.json\").decode(\"utf-8\"))\n        manifest_body = envelope[\"manifest\"]\n        canonical_json = json.dumps(manifest_body, sort_keys=True, separators=(\",\", \":\")).encode(\"utf-8\")\n        actual_sig = hmac.new(key, canonical_json, hashlib.sha256).hexdigest()\n        if not hmac.compare_digest(envelope[\"hmac_sha256\"], actual_sig):\n            raise ValueError(\"HMAC_SIGNATURE_MISMATCH: Manifest mungkin dipalsukan!\")\n        loaded = {}\n        for fname, meta in manifest_body[\"tensors\"].items():\n            raw_npy = zf.read(fname)\n            if not hmac.compare_digest(hashlib.sha256(raw_npy).hexdigest(), meta[\"sha256\"]):\n                raise ValueError(f\"SHA256_TAMPER_DETECTED pada {fname}!\")\n            loaded[fname] = np.load(io.BytesIO(raw_npy), allow_pickle=False)\n        return loaded\n\ndef infer_pure_numpy(params: dict[str, np.ndarray], X_in: np.ndarray) -> np.ndarray:\n    z_scaled = (X_in - params[\"scaler_mean.npy\"]) / params[\"scaler_scale.npy\"]\n    logits = z_scaled @ params[\"clf_coef.npy\"].T + params[\"clf_intercept.npy\"]\n    return 1.0 / (1.0 + np.exp(-logits.ravel()))\n\nbundle = save_safe_bundle(pipe, SECRET_KEY)\nreloaded = load_and_verify_safe_bundle(bundle, SECRET_KEY)\nprobs_reloaded = infer_pure_numpy(reloaded, X[:100])\nmax_abs_diff = float(np.max(np.abs(probs_orig - probs_reloaded)))\n\n# 3. Uji 1-Bit Tampering Attack pada bobot model\ntampered_buf = io.BytesIO()\nwith zipfile.ZipFile(io.BytesIO(bundle), \"r\") as zin, zipfile.ZipFile(tampered_buf, \"w\") as zout:\n    for item in zin.infolist():\n        data = zin.read(item.filename)\n        if item.filename == \"clf_coef.npy\":\n            b = bytearray(data)\n            b[-1] ^= 0x01\n            data = bytes(b)\n        zout.writestr(item, data)\n\ntry:\n    load_and_verify_safe_bundle(tampered_buf.getvalue(), SECRET_KEY)\n    tamper_result = \"BYPASSED (BAHAYA!)\"\nexcept ValueError as err:\n    tamper_result = f\"BLOCKED ({err})\"\n\nprint(f\"Ukuran Safe Zero-Pickle Bundle : {len(bundle)} bytes (ZIP + JSON Manifest + .npy allow_pickle=False)\")\nprint(f\"Verifikasi Bit-Parity (N=100)  : max|p_sklearn - p_numpy| = {max_abs_diff:.3e} (Exact Parity!)\")\nprint(f\"Uji 1-Bit Tampering Attack     : {tamper_result}\")",
