          "code": "import math\nimport numpy as np\n\n# Simulasi 2 Skenario Insiden pada Multi-Signal Automated Rollback Circuit Breaker\n# Total trafik = 400 req/dtk | Canary 5% = 20 req/dtk | Fault dimulai pada detik t = 15s\nTOTAL_RPS, CANARY_RPS, FAULT_SEC = 400, 20, 15\np0, p1 = 0.008, 0.030\nA_thresh = math.log((1.0 - 0.05) / 0.005)\nllr_1 = math.log(p1 / p0)\nllr_0 = math.log((1.0 - p1) / (1.0 - p0))\n\ndef run_incident_sim(seed: int, fault_err: float, fault_lat_med: float, fault_score_mean: float):\n    rng = np.random.default_rng(seed)\n    llr_cum, lat_streak, shift_streak = 0.0, 0, 0\n    rollback_sec, trigger_reason, impacted = None, \"NONE\", 0\n    for sec in range(1, 121):\n        if rollback_sec is not None:\n            break\n        is_fault = sec >= FAULT_SEC\n        errs = rng.binomial(1, fault_err if is_fault else p0, size=CANARY_RPS)\n        lats = rng.lognormal(np.log(fault_lat_med if is_fault else 11.0), 0.25, size=CANARY_RPS)\n        scores = np.clip(rng.normal(fault_score_mean if is_fault else 0.12, 0.08, size=CANARY_RPS), 0.0, 1.0)\n        if is_fault:\n            impacted += CANARY_RPS\n        # CUSUM-SPRT (Page 1954): reset di 0 agar sensitif instan saat fault muncul di tengah jalan!\n        for e in errs:\n            llr_cum = max(0.0, llr_cum + (llr_1 if e == 1 else llr_0))\n        p99_sec = float(np.quantile(lats, 0.99))\n        mean_shift = abs(float(np.mean(scores)) - 0.12)\n        lat_streak = lat_streak + 1 if p99_sec > 25.0 else 0\n        shift_streak = shift_streak + 1 if mean_shift > 0.18 else 0\n\n        reasons = []\n        if llr_cum >= A_thresh:\n            reasons.append(f\"CUSUM_SPRT(LLR={llr_cum:.2f}>={A_thresh:.2f})\")\n        if lat_streak >= 3:\n            reasons.append(f\"LATENCY_P99({p99_sec:.1f}ms>25ms x3s)\")\n        if shift_streak >= 3:\n            reasons.append(f\"SCORE_SHIFT(dMean={mean_shift:.2f}>0.18 x3s)\")\n        if reasons:\n            rollback_sec = sec\n            trigger_reason = \" + \".join(reasons)\n    return rollback_sec, (rollback_sec - FAULT_SEC) if rollback_sec else -1, trigger_reason, impacted\n\nmanual_impacted = TOTAL_RPS * 1800  # 30 menit deteksi manual pada Blue-Green 100%\n\nprint(\"=== MULTI-SIGNAL AUTOMATED ROLLBACK CIRCUIT BREAKER (CANARY 5% = 20 REQ/DTK) ===\")\nfor title, args in [\n    (\"Skenario A (Hard Fault: Latensi + Score Shift)\", (42, 0.032, 19.5, 0.36)),\n    (\"Skenario B (Silent Fault: Hanya Error 0.8%->3.2%)\", (43, 0.032, 11.0, 0.12)),\n]:\n    rb_s, ttd, reason, imp = run_incident_sim(*args)\n    red = (1.0 - imp / manual_impacted) * 100.0\n    print(f\"\\n[{title}]\")\n    print(f\"  Rollback t={rb_s}s (TTD={ttd} detik!) | Trigger: {reason}\")\n    print(f\"  Blast Radius: {imp} req terdampak vs {manual_impacted} req manual ({red:.4f}% terselamatkan)\")",
